// Sniperモード自動最適化 2026-05-13 12:55 / 1428件データ
// Sniper: 14件 勝率78.6% 平均2.0%
// 【Sniper条件（全6条件通過で採択）】
//   ① close > EMA25（中期トレンド）
//   ② 強い陽線（実体≥0.5%）
//   ③ ATR% < 5.0%
//   ④ 直近20日高値更新
//   ⑤ RSI 40〜60
//   ⑥ 一目: close > 26日前終値

function calculateScoreSniper(ind) {
  if (!ind) return null;
  const filters = [];
  let score = 0;

  // ① close > EMA25（中期トレンド）
  if (ind.ema25 !== null && ind.close > ind.ema25) {
    score++;
    filters.push(`①EMA25順張り`);
  }

  // ② 強い陽線（実体≥0.5%）
  if (ind.isStrongBull) {
    score++;
    filters.push(`②強陽線(${ind.bodyPct.toFixed(1)}%)`);
  }

  // ③ ATR% < 5.0%
  if (ind.atrPct < 5.0) {
    score++;
    filters.push(`③ATR(${ind.atrPct}%)`);
  }

  // ④ 直近20日高値更新
  if (ind.hiBrk20) {
    score++;
    filters.push(`④高値更新`);
  }

  // ⑤ RSI 40〜60
  if (!isNaN(ind.rsi14) && ind.rsi14 >= 40 && ind.rsi14 < 60) {
    score++;
    filters.push(`⑤RSI(${ind.rsi14.toFixed(0)})`);
  }

  // ⑥ 一目: close > 26日前終値
  if (ind.ichChikou) {
    score++;
    filters.push(`⑥一目遅行`);
  }

  return { score, filters };
}
